// Vendored from the dart_tui fork (`vendor/dart_tui/lib/src/editor.dart`, issue
// #613): hosted dart_tui ships no editor, so the published package cannot
// reference the fork-only symbol — the composer carries its own copy instead.
// Types renamed Tui* so they coexist with the fork barrel's own exports
// (published builds resolve hosted dart_tui, which exports neither).
// Otherwise byte-identical to the fork source; keep in sync when
// the fork editor changes.
// TuiLineEditor: readline-grade immutable line editing for the TUI composer
// (issue #275 scope 3). Value semantics — every mutation returns a new
// TuiLineEditor, so FaTuiModel.copyWith can carry it like any other field.
//
// Features: kill-ring (ctrl-w/u/k cut, ctrl-y yank, ring of 8, per-session
// by construction), grouped undo (word-wise coalescing, cap 100 steps),
// ctrl-t transpose. Paste inserts verbatim like any other text.
library;

/// One immutable line-buffer snapshot: [text] with the caret at [cursor].
class TuiLineBuffer {
  final String text;
  final int cursor;

  const TuiLineBuffer(this.text, [this.cursor = 0]);

  String get before => text.substring(0, cursor.clamp(0, text.length));
  String get after => text.substring(cursor.clamp(0, text.length));
}

/// A single undo step: the buffer BEFORE the change plus a grouping tag.
/// Consecutive steps with the same tag coalesce into one undo (word
/// grouping: typing "hello world" undoes one word at a time, not per key).
class _UndoStep {
  final TuiLineBuffer buffer;
  final Object group;

  const _UndoStep(this.buffer, this.group);
}

