/// files are still checked for the unambiguous `<<<<<<<`/`>>>>>>>` shapes.
final _markerPatterns = [RegExp(r'^<<<<<<<($| )'), RegExp(r'^>>>>>>>($| )')];
const _mdOnlySafeMarker = r'^=======$';

